private lemma hasDerivAt_sine_half_sub (r t : ℝ) :
    HasDerivAt (fun u : ℝ => Real.sin ((u - r) / 2))
      (Real.cos ((t - r) / 2) / 2) t

private lemma hasDerivAt_cosine_half_sub_div_two (r t : ℝ) :
