lemma sin_numerator_pos_on_wrapGap (angles : CyclicAngles n hn) {t : ℝ}
    (ht : t ∈ wrapGap angles) (k : Fin n) :
    0 < Real.sin ((t - angles.angle k) / 2)

theorem abs_sineCardinal_on_wrapGap (angles : CyclicAngles n hn) {t : ℝ}
    (ht : t ∈ wrapGap angles) (j : Fin n) :
    |sineCardinal angles.angle j t| = wrapCoefficient j * sineCardinal angles.angle j t

lemma wrapCoefficient_mul_sineCardinal_pos (angles : CyclicAngles n hn) {t : ℝ}
    (ht : t ∈ wrapGap angles) (j : Fin n) :
    0 < wrapCoefficient j * sineCardinal angles.angle j t

theorem sineLebesgueFunction_on_wrapGap (angles : CyclicAngles n hn) {t : ℝ}
    (ht : t ∈ wrapGap angles) :
    (∑ j, |sineCardinal angles.angle j t|) = sineInterpolant angles.angle wrapCoefficient t

lemma finiteRootProduct_eq_mul_complement {m : ℕ}
    (d : Fin m → ℝ) (k : Fin m) :
    finiteRootProduct d = (X - C (d k)) * finiteRootComplement d k

lemma finiteRootComplement_eval_self_ne_zero {m : ℕ}
    {d : Fin m → ℝ} (hd : Function.Injective d) (k : Fin m) :
    (finiteRootComplement d k).eval (d k) ≠ 0

lemma finiteRootBasis_eval_self {m : ℕ} {d : Fin m → ℝ}
    (hd : Function.Injective d) (k : Fin m) :
    (finiteRootBasis d k).eval (d k) = 1

lemma finiteRootBasis_eval_of_ne {m : ℕ} {d : Fin m → ℝ}
    (k l : Fin m) (hlk : l ≠ k) :
    (finiteRootBasis d k).eval (d l) = 0

lemma finiteRootBasis_eq_lagrangeBasis {m : ℕ}
    {d : Fin m → ℝ} (hd : Function.Injective d) (k : Fin m) :
    finiteRootBasis d k = Lagrange.basis Finset.univ d k

lemma finiteRootInterpolant_degree_lt {m : ℕ}
    {d : Fin m → ℝ} (hd : Function.Injective d) (S : ℝ[X]) :
    (finiteRootInterpolant d S).degree < m

lemma exists_finiteRootComplement_eval_ne_zero {m : ℕ}
    (hm : 0 < m) {d : Fin m → ℝ} (hd : Function.Injective d) (x : ℝ) :
    ∃ k : Fin m, (finiteRootComplement d k).eval x ≠ 0

lemma angle_lt_of_crossSumRootLocation_of_lt (angles : CyclicAngles n hn)
